     1→/**
     2→ * Image Generation Service
     3→ * Client for OpenRouter API using Gemini 2.5 Flash Preview Image model for outfit visualization
     4→ *
     5→ * Features:
     6→ * - Fashion-specific prompt engineering
     7→ * - Error handling with retries
     8→ * - Timeout protection
     9→ * - Rate limiting awareness
    10→ */
    11→
    12→import type { ImageGenerationRequest, ImageGenerationResponse } from '../types/image-types';
    13→
    14→/**
    15→ * OpenRouter API configuration
    16→ */
    17→const OPENROUTER_CONFIG = {
    18→  /** OpenRouter API base URL */
    19→  baseUrl: 'https://openrouter.ai/api/v1',
    20→  /**
    21→   * Model ID for Gemini 3 Pro Image Preview - Nano Banana Pro (text-to-image capable)
    22→   * Google's most advanced image-generation and editing model
    23→   */
    24→  model: 'google/gemini-2.5-flash-image',
    25→  /** Request timeout in milliseconds */
    26→  timeout: 30000,
    27→  /** Maximum retry attempts on failure */
    28→  maxRetries: 2,
    29→  /** Exponential backoff base delay (ms) */
    30→  retryDelay: 1000,
    31→};
    32→
    33→/**
    34→ * OpenRouter Image Generation Client
    35→ * Handles communication with OpenRouter API for outfit image generation
    36→ */
    37→export class OpenRouterImageClient {
    38→  private apiKey: string;
    39→  private requestCount: number = 0;
    40→  private lastRequestTime: number = 0;
    41→
    42→  /**
    43→   * Creates a new OpenRouter image client
    44→   *
    45→   * @param apiKey - OpenRouter API key
    46→   * @throws Error if API key is not provided
    47→   */
    48→  constructor(apiKey: string) {
    49→    if (!apiKey || typeof apiKey !== 'string' || apiKey.trim() === '') {
    50→      throw new Error('OpenRouter API key is required');
    51→    }
    52→    this.apiKey = apiKey;
    53→  }
    54→
    55→  /**
    56→   * Generates an outfit image from description using Gemini 2.5 Flash Preview
    57→   *
    58→   * @param description - Outfit description extracted from conversation
    59→   * @param options - Optional style parameters
    60→   * @returns Promise resolving to image generation response
    61→   *
    62→   * @example
    63→   * const client = new OpenRouterImageClient(apiKey);
    64→   * const response = await client.generateOutfitImage(
    65→   *   "White shirt with black pants for business meeting",
    66→   *   { style: { composition: 'flat-lay' } }
    67→   * );
    68→   */
    69→  async generateOutfitImage(
    70→    description: string,
    71→    options?: ImageGenerationRequest['style']
    72→  ): Promise<ImageGenerationResponse> {
    73→    // Validate input
    74→    if (!description || typeof description !== 'string' || description.trim() === '') {
    75→      return {
    76→        success: false,
    77→        error: 'INVALID_DESCRIPTION',
    78→        message: 'Outfit description is required',
    79→      };
    80→    }
    81→
    82→    // Check client-side rate limiting (basic protection)
    83→    if (!this.checkRateLimit()) {
    84→      return {
    85→        success: false,
    86→        error: 'RATE_LIMITED',
    87→        message: 'Too many requests. Please wait a moment before trying again.',
    88→      };
    89→    }
    90→
    91→    // Attempt generation with retries
    92→    let lastError: Error | null = null;
    93→
    94→    for (let attempt = 0; attempt <= OPENROUTER_CONFIG.maxRetries; attempt++) {
    95→      try {
    96→        if (attempt > 0) {
    97→          // Exponential backoff delay
    98→          const delay = OPENROUTER_CONFIG.retryDelay * Math.pow(2, attempt - 1);
    99→          await this.sleep(delay);
   100→          console.log(`[ImageGen] Retry attempt ${attempt}/${OPENROUTER_CONFIG.maxRetries}`);
   101→        }
   102→
   103→        const result = await this.makeRequest(description, options);
   104→        return result;
   105→      } catch (error) {
   106→        lastError = error as Error;
   107→        console.error(`[ImageGen] Attempt ${attempt + 1} failed:`, error);
   108→
   109→        // Don't retry on certain errors
   110→        if (this.isNonRetryableError(error)) {
   111→          break;
   112→        }
   113→      }
   114→    }
   115→
   116→    // All retries failed
   117→    return {
   118→      success: false,
   119→      error: 'GENERATION_FAILED',
   120→      message: 'Unable to generate image. Please try again later.',
   121→    };
   122→  }
   123→
   124→  /**
   125→   * Makes the actual API request to OpenRouter
   126→   *
   127→   * @private
   128→   */
   129→  private async makeRequest(
   130→    description: string,
   131→    options?: ImageGenerationRequest['style']
   132→  ): Promise<ImageGenerationResponse> {
   133→    // Build fashion-specific prompt
   134→    const prompt = this.buildFashionPrompt(description, options);
   135→
   136→    // Create request payload - OpenRouter image generation requires messages format with modalities
   137→    const requestBody = {
   138→      model: OPENROUTER_CONFIG.model,
   139→      messages: [
   140→        {
   141→          role: 'user',
   142→          content: prompt,
   143→        },
   144→      ],
   145→      modalities: ['text', 'image'], // Required for image generation
   146→      max_tokens: 4096, // For image generation
   147→    };
   148→
   149→    console.log('[ImageGen] Sending request to OpenRouter:', {
   150→      model: requestBody.model,
   151→      promptLength: prompt.length,
   152→    });
   153→
   154→    // Create abort controller for timeout
   155→    const controller = new AbortController();
   156→    const timeoutId = setTimeout(() => controller.abort(), OPENROUTER_CONFIG.timeout);
   157→
   158→    try {
   159→      const response = await fetch(`${OPENROUTER_CONFIG.baseUrl}/chat/completions`, {
